export const notificationRouter = router({
  markAsRead: protectedProcedure
    .input(z.object({ notificationId: z.string().cuid() }))
    .mutation(async ({ input, ctx }) => {
      const notification = await ctx.prisma.inAppNotification.findFirst({
        where: { id: input.notificationId, recipientId: ctx.user.id },
      });
      if (!notification) throw new TRPCError({ code: 'NOT_FOUND', message: 'Notification not found' });
      const updated = await ctx.prisma.inAppNotification.update({
        where: { id: input.notificationId },
        data: { isRead: true },
      });
      return { success: true, id: updated.id };
    }),
});
